classdef report_scripts
% REPORT_SCRIPTS  Shared inline JavaScript for PRESTUS HTML reports.
%
% All methods are static and return a self-contained <script> string (no
% external dependencies, so reports stay offline-portable). The MATLAB side
% still produces any data payloads (via jsonencode); only the behaviour lives
% here, shared by the per-subject and group reports.
%
% Methods:
%   report_scripts.common()         theme toggle, in-page search, scroll-spy,
%                                    meter-fill animation, lightbox (zoom +
%                                    side-by-side compare), figure download
%                                    chips, SVG/PNG export of svg.chart plots,
%                                    methods copy buttons
%   report_scripts.group_runtime()  sortable roster + client-side analysis
%                                    charts (reads PRESTUS_SUBJECTS / _METRICS)
%
% See also: GENERATE_SIMULATION_REPORT, GENERATE_GROUP_REPORT, CSS_STYLES_BASE

    methods (Static)

        function html = common()
        % Theme, search, scroll-spy, meter fill, and the lightbox behaviour.
            js = [ ...
'(function(){var root=document.documentElement;' ...
'function setTheme(t){root.setAttribute("data-theme",t);' ...
'var s=document.getElementById("theme-sun"),m=document.getElementById("theme-moon");' ...
'if(s)s.style.display=t==="dark"?"none":"block";if(m)m.style.display=t==="dark"?"block":"none";' ...
'try{localStorage.setItem("prestus-theme",t);}catch(e){}}' ...
'var stored=null;try{stored=localStorage.getItem("prestus-theme");}catch(e){}' ...
'setTheme(stored||(window.matchMedia&&matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light"));' ...
'var tb=document.getElementById("theme-btn");if(tb)tb.addEventListener("click",function(){setTheme(root.getAttribute("data-theme")==="dark"?"light":"dark");});' ...
... % meter fill (setTimeout fires even when the tab is backgrounded)
'setTimeout(function(){[].forEach.call(document.querySelectorAll(".safety-bar[data-pct]"),function(b){var p=Math.min(100,Math.max(2,parseFloat(b.getAttribute("data-pct"))))+"%";b.style.width="0%";void b.offsetWidth;b.style.width=p;});},60);' ...
... % scroll-spy
'var links=[].slice.call(document.querySelectorAll(".toc a[href^=\"#\"]"));' ...
'var secs=links.map(function(a){return document.querySelector(a.getAttribute("href"));}).filter(Boolean);' ...
'if(window.IntersectionObserver){var sp=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){links.forEach(function(l){l.classList.toggle("active",l.getAttribute("href")==="#"+e.target.id);});}});},{rootMargin:"-45% 0px -50% 0px"});secs.forEach(function(s){sp.observe(s);});}' ...
... % in-page search highlight
'var si=document.getElementById("report-search");' ...
'function unmark(scope){[].forEach.call(scope.querySelectorAll("mark.s"),function(m){var t=document.createTextNode(m.textContent);m.parentNode.replaceChild(t,m);});}' ...
'function walk(node,rx){if(node.nodeType===3){rx.lastIndex=0;if(rx.test(node.nodeValue)){var span=document.createElement("span");' ...
'node.nodeValue.split(rx).forEach(function(p,i){if(!p)return;if(i%2){var mk=document.createElement("mark");mk.className="s";mk.textContent=p;span.appendChild(mk);}else span.appendChild(document.createTextNode(p));});' ...
'node.parentNode.replaceChild(span,node);return span;}return null;}' ...
'if(node.nodeType===1&&!/SCRIPT|STYLE|MARK|INPUT|TEXTAREA/.test(node.tagName)){var first=null;[].slice.call(node.childNodes).forEach(function(c){var r=walk(c,rx);if(r&&!first)first=r;});return first;}return null;}' ...
'function runSearch(q){var scopes=document.querySelectorAll(".report-section");[].forEach.call(scopes,unmark);' ...
'if(!q||q.length<2)return;var rx=new RegExp("("+q.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")+")","gi");var first=null;' ...
'[].forEach.call(document.querySelectorAll(".report-section"),function(c){var opened=false;if(c.tagName==="DETAILS"&&!c.open){c.open=true;opened=true;}var f=walk(c,rx);if(f&&!first)first=f;if(opened&&!c.querySelector("mark.s"))c.open=false;});' ...
'if(first)first.scrollIntoView({behavior:"smooth",block:"center"});}' ...
'if(si){var dt;si.addEventListener("input",function(e){clearTimeout(dt);var v=e.target.value.trim();dt=setTimeout(function(){runSearch(v);},200);});}' ...
'document.addEventListener("keydown",function(e){if(e.key==="/"&&si&&document.activeElement!==si&&!/INPUT|TEXTAREA/.test(document.activeElement.tagName)){e.preventDefault();si.focus();}});' ...
... % download helpers: data: URIs go through fetch->blob so large images save reliably
'function dlBlob(b,name){var u=URL.createObjectURL(b);var a=document.createElement("a");a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(u);},1500);}' ...
'function dl(src,name){fetch(src).then(function(r){return r.blob();}).then(function(b){dlBlob(b,name);});}' ...
'function slug(s){return (s||"").trim().replace(/[^\w.-]+/g,"_").replace(/^_+|_+$/g,"").slice(0,90)||"plot";}' ...
'function figName(fig){return fig.getAttribute("data-file")||slug(fig.getAttribute("data-cap"))+".png";}' ...
... % interactive SVG charts: inline the theme's CSS variables so the export keeps its colours
'function svgBlob(svg){var c=svg.cloneNode(true),cs=getComputedStyle(document.documentElement),vb=svg.viewBox.baseVal;' ...
'[c].concat([].slice.call(c.querySelectorAll("*"))).forEach(function(e){[].slice.call(e.attributes).forEach(function(a){if(a.value.indexOf("var(")>-1)e.setAttribute(a.name,a.value.replace(/var\((--[\w-]+)\)/g,function(m,v){return cs.getPropertyValue(v).trim()||"#888";}));});});' ...
'c.removeAttribute("style");c.setAttribute("xmlns","http://www.w3.org/2000/svg");c.setAttribute("width",vb.width);c.setAttribute("height",vb.height);c.setAttribute("font-family",getComputedStyle(svg).fontFamily);' ...
'var bg=document.createElementNS("http://www.w3.org/2000/svg","rect");bg.setAttribute("x",vb.x);bg.setAttribute("y",vb.y);bg.setAttribute("width",vb.width);bg.setAttribute("height",vb.height);bg.setAttribute("fill",cs.getPropertyValue("--surface-2").trim()||"#fff");c.insertBefore(bg,c.firstChild);' ...
'return new Blob([new XMLSerializer().serializeToString(c)],{type:"image/svg+xml"});}' ...
'function svgPng(svg,name){var u=URL.createObjectURL(svgBlob(svg)),im=new Image(),vb=svg.viewBox.baseVal;im.onload=function(){var cv=document.createElement("canvas");cv.width=vb.width*2;cv.height=vb.height*2;cv.getContext("2d").drawImage(im,0,0,cv.width,cv.height);URL.revokeObjectURL(u);cv.toBlob(function(p){dlBlob(p,name+".png");});};im.src=u;}' ...
'function chartName(el){var h3="",h4="";for(var n=el;n&&n!==document.body&&!h3;n=n.parentNode){for(var p=n.previousElementSibling;p;p=p.previousElementSibling){if(p.tagName==="H4"&&!h4)h4=p.textContent;if(/^H[23]$/.test(p.tagName)){h3=p.textContent;break;}}}return slug((h3||el.id||"chart")+(h4?"_"+h4:""));}' ...
'[].forEach.call(document.querySelectorAll("svg.chart"),function(svg){var bar=document.createElement("div");bar.className="chart-tools";' ...
'[["SVG",function(){dlBlob(svgBlob(svg),chartName(svg)+".svg");}],["PNG",function(){svgPng(svg,chartName(svg));}]].forEach(function(b){var e=document.createElement("button");e.type="button";e.textContent="⤓ "+b[0];e.addEventListener("click",b[1]);bar.appendChild(e);});' ...
'svg.parentNode.insertBefore(bar,svg.nextSibling);});' ...
... % lightbox + zoom + compare
'var lb=document.getElementById("lightbox");if(lb){var stage=document.getElementById("lb-stage"),cmp=[],cur=[],zoom=1;' ...
'function apply(){[].forEach.call(stage.querySelectorAll("img"),function(i){i.style.transform="scale("+zoom+")";});}' ...
'function show(items){stage.innerHTML="";zoom=1;cur=items;items.forEach(function(it){var fg=document.createElement("figure");var im=document.createElement("img");im.src=it.src;fg.appendChild(im);if(it.cap){var fc=document.createElement("figcaption");fc.textContent=it.cap;fg.appendChild(fc);}stage.appendChild(fg);});stage.classList.toggle("pair",items.length>1);lb.style.display="flex";apply();}' ...
'function close(){lb.style.display="none";}' ...
'var zb=document.getElementById("lb-zoom");if(zb)zb.addEventListener("click",function(){zoom=Math.min(3,zoom+0.4);apply();});' ...
'var rb=document.getElementById("lb-reset");if(rb)rb.addEventListener("click",function(){zoom=1;apply();});' ...
'var db=document.getElementById("lb-dl");if(db)db.addEventListener("click",function(){cur.forEach(function(it){dl(it.src,it.name);});});' ...
'var cb=lb.querySelector(".lb-close");if(cb)cb.addEventListener("click",close);' ...
'lb.addEventListener("click",function(e){if(e.target===lb)close();});' ...
'document.addEventListener("keydown",function(e){if(e.key==="Escape")close();});' ...
'[].forEach.call(document.querySelectorAll(".image-grid figure,.image-grid--3col figure,.image-grid--wide figure,.image-grid--narrow figure"),function(fig){' ...
'var img=fig.querySelector("img");if(!img)return;var cap=fig.querySelector("figcaption");' ...
'fig.setAttribute("data-cap",cap?cap.textContent:"");fig._lbItem={src:img.src,cap:cap?cap.textContent:"",name:figName(fig)};' ... % caption text before the buttons are appended
'var btn=document.createElement("span");btn.className="cmp";btn.textContent="compare";btn.title="Mark two figures to view them side by side";' ...
'var dlb=document.createElement("span");dlb.className="dl";dlb.textContent="download";dlb.title="Download "+figName(fig);' ...
'dlb.addEventListener("click",function(e){e.stopPropagation();dl(img.src,figName(fig));});' ...
'if(cap){cap.appendChild(btn);cap.appendChild(dlb);}else{fig.appendChild(btn);fig.appendChild(dlb);}' ...
... % toggle mark; marking a second figure opens the pair straight away
'btn.addEventListener("click",function(e){e.stopPropagation();var i=cmp.indexOf(fig);if(i>-1){cmp.splice(i,1);btn.classList.remove("on");return;}' ...
'if(cmp.length>=2){var old=cmp.shift();var ob=old.querySelector(".cmp");if(ob)ob.classList.remove("on");}cmp.push(fig);btn.classList.add("on");' ...
'if(cmp.length===2)show([cmp[0]._lbItem,cmp[1]._lbItem]);});' ...
... % image click: either marked figure of a pair -> pair; one other marked -> pair; else single
'img.addEventListener("click",function(){var self=fig._lbItem;' ...
'if(cmp.length===2&&cmp.indexOf(fig)>-1)show([cmp[0]._lbItem,cmp[1]._lbItem]);' ...
'else if(cmp.length===1&&cmp[0]!==fig)show([cmp[0]._lbItem,self]);' ...
'else show([self]);});});}' ...
... % methods: copy text (+ references) as rich HTML and plain text for manuscripts
'var mt=document.getElementById("methods-text");if(mt){' ...
'function mplain(n){var c=n.cloneNode(true);[].forEach.call(c.querySelectorAll("sup"),function(x){x.textContent="^("+x.textContent+")";});' ...
'return [].map.call(c.querySelectorAll("p,li"),function(x){return x.textContent.replace(/\s+/g," ").trim();}).join("\n\n");}' ...
'function mcopy(btn){var box=document.createElement("div");box.appendChild(mt.cloneNode(true));var withRefs=btn.getAttribute("data-refs")==="1",rl=document.querySelector("#methods-refs ol");' ...
'if(withRefs&&rl){var h=document.createElement("p");h.innerHTML="<strong>References</strong>";box.appendChild(h);box.appendChild(rl.cloneNode(true));}' ...
'var html=box.innerHTML,text=mplain(box);if(withRefs&&rl)text=text.replace(/\n\nReferences\n\n/,"\n\nReferences\n");' ...
