'function fallback(){var tmp=document.createElement("div");tmp.contentEditable="true";tmp.style.cssText="position:fixed;left:-9999px;top:0";tmp.innerHTML=html;document.body.appendChild(tmp);' ...
'var r=document.createRange();r.selectNodeContents(tmp);var sel=window.getSelection();sel.removeAllRanges();sel.addRange(r);var ok=false;try{ok=document.execCommand("copy");}catch(e){}sel.removeAllRanges();document.body.removeChild(tmp);done(ok);}' ...
'if(navigator.clipboard&&window.ClipboardItem&&window.isSecureContext){navigator.clipboard.write([new ClipboardItem({"text/html":new Blob([html],{type:"text/html"}),"text/plain":new Blob([text],{type:"text/plain"})})]).then(function(){done(true);},fallback);}else fallback();}' ...
'[].forEach.call(document.querySelectorAll(".methods-copy"),function(b){b.addEventListener("click",function(){mcopy(b);});});}' ...
'})();' ];
            html = ['<script>' js '</script>'];
        end

        function html = group_runtime()
        % Sortable roster + analysis charts. Expects two globals already
        % emitted by the report: PRESTUS_SUBJECTS (array of {id, <metric>:val})
        % and PRESTUS_METRICS (array of {k,label,unit,limit,dom}).
            js = [ ...
'(function(){if(!window.PRESTUS_SUBJECTS||!window.PRESTUS_METRICS)return;' ...
'var SUB=window.PRESTUS_SUBJECTS,MET=window.PRESTUS_METRICS;' ...
'var byK={};MET.forEach(function(m){byK[m.k]=m;});' ...
'function isLim(m){return m&&isFinite(m.limit);}' ...
'function cls(v,lim){if(!isFinite(lim))return"info";if(v>lim)return"red";if(v>=0.5*lim)return"amber";return"green";}' ...
... % --- sortable roster (sorts existing server-rendered rows) ---
'var tbl=document.getElementById("roster-table");' ...
'if(tbl){var tb=tbl.tBodies[0];var sortKey=null,dir=1;' ...
